import type { Placement, UseFloatingReturn, useInteractions } from "@floating-ui/react";

import { createContext, useContext } from "react";

export interface ComboboxFloatingContextType {
  floatingStyles: UseFloatingReturn["floatingStyles"];
  floatingContext: UseFloatingReturn["context"];
  getReferenceProps: ReturnType<typeof useInteractions>["getReferenceProps"];
  getFloatingProps: ReturnType<typeof useInteractions>["getFloatingProps"];
  isMounted: boolean;
  refs: UseFloatingReturn["refs"];
  styles: React.CSSProperties;
  currentOpenState: boolean;
  actualPlacement: Placement;
  setOpen: (open: boolean) => void;
  activeIndex: number | null;
  listRef: React.MutableRefObject<Array<HTMLElement | null>>;
}

export const ComboboxFloatingContext = createContext<ComboboxFloatingContextType | undefined>(
  undefined,
);

export const useComboboxFloating = () => {
  const context = useContext(ComboboxFloatingContext);
  if (!context) {
    throw new Error("useComboboxFloating must be used within a Combobox component");
  }
  return context;
};
